/** Generated by scaffold-crud-pages. Query hooks for QuizAnswers.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchQuizAnswersList,
  fetchQuizAnswersById,
  createQuizAnswers,
  updateQuizAnswers,
  deleteQuizAnswers,
  type FetchQuizAnswersListParams,
} from '~/services/httpServices/quizAnswersService';
import type { CreateQuizAnswersRequest, UpdateQuizAnswersRequest } from '~/types/quiz-answers';

const DOMAIN = 'quizAnswers';

export function useQuizAnswersList(params?: FetchQuizAnswersListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchQuizAnswersList(params),
  });
}

export function useQuizAnswers(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchQuizAnswersById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateQuizAnswers() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateQuizAnswersRequest) => createQuizAnswers(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateQuizAnswers() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateQuizAnswersRequest }) =>
      updateQuizAnswers(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteQuizAnswers() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteQuizAnswers(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
